import numpy as np
from scipy.optimize import minimize
import random

class HybridGA:
    def __init__(self, budget=10000, dim=10, pop_size=20, mutation_rate=0.1, crossover_rate=0.8, local_search_steps=10):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.local_search_steps = local_search_steps
        self.lb = -5.0
        self.ub = 5.0
        self.evals = 0

    def _initialize_population(self):
        return np.random.uniform(self.lb, self.ub, size=(self.pop_size, self.dim))

    def _evaluate_population(self, func, population):
        fitness = np.zeros(self.pop_size)
        for i in range(self.pop_size):
            if self.evals < self.budget:
                fitness[i] = func(population[i])
                self.evals += 1
            else:
                fitness[i] = np.inf  # Assign a large value if budget is exceeded
        return fitness

    def _selection(self, population, fitness):
        # Tournament selection
        selected_indices = []
        for _ in range(self.pop_size):
            tournament_indices = np.random.choice(self.pop_size, size=2, replace=False)
            if fitness[tournament_indices[0]] < fitness[tournament_indices[1]]:
                selected_indices.append(tournament_indices[0])
            else:
                selected_indices.append(tournament_indices[1])
        return population[selected_indices]

    def _crossover(self, parents):
        offspring = []
        for i in range(0, self.pop_size, 2):
            if random.random() < self.crossover_rate and i + 1 < self.pop_size:
                # Single-point crossover
                crossover_point = random.randint(1, self.dim - 1)
                parent1 = parents[i % self.pop_size]
                parent2 = parents[(i + 1) % self.pop_size]
                offspring1 = np.concatenate((parent1[:crossover_point], parent2[crossover_point:]))
                offspring2 = np.concatenate((parent2[:crossover_point], parent1[crossover_point:]))
                offspring.extend([offspring1, offspring2])
            else:
                offspring.append(parents[i % self.pop_size])
                if i+1 < self.pop_size:
                    offspring.append(parents[(i+1)% self.pop_size])
        return np.array(offspring)[:self.pop_size] # Ensure correct size

    def _mutation(self, population):
        for i in range(self.pop_size):
            for j in range(self.dim):
                if random.random() < self.mutation_rate:
                    population[i, j] = np.random.uniform(self.lb, self.ub)
        return population

    def _local_search(self, func, x_best):
        if self.evals >= self.budget:
            return x_best

        result = minimize(func, x_best, method='Nelder-Mead', bounds=[(self.lb, self.ub)] * self.dim, options={'maxiter': self.local_search_steps, 'maxfev': self.budget - self.evals})

        if result.success:
            return result.x
        else:
            return x_best  # Return the original best if local search fails

    def __call__(self, func):
        population = self._initialize_population()
        best_fitness = np.inf
        best_solution = None

        for generation in range(self.budget // (self.pop_size + self.local_search_steps) + 1):  # Adjust the number of generations based on budget

            fitness = self._evaluate_population(func, population)

            for i in range(self.pop_size):
                if fitness[i] < best_fitness:
                    best_fitness = fitness[i]
                    best_solution = population[i].copy() # Ensure we create a copy
            if self.evals >= self.budget:
                break

            parents = self._selection(population, fitness)

            offspring = self._crossover(parents)

            mutated_offspring = self._mutation(offspring)

            new_population = mutated_offspring

            new_fitness = self._evaluate_population(func, new_population)

            combined_population = np.concatenate((population, new_population), axis=0)
            combined_fitness = np.concatenate((fitness, new_fitness))

            # Keep only the best 'pop_size' members
            combined_indices = np.argsort(combined_fitness)
            population = combined_population[combined_indices[:self.pop_size]]


            best_individual_index = np.argmin(self._evaluate_population(func, population))
            best_individual = population[best_individual_index]


            best_solution = self._local_search(func, best_individual)

            if self.evals >= self.budget:
                break

            best_fitness = func(best_solution) # Recalculate fitness for updated best

            if self.evals > self.budget:
                break


        return best_fitness, best_solution
